(1, 1, 'insert', '{\n    \"action\": \"propose_action\",\n    \"action_type\": \"insert\",\n    \"target_table\": \"posts\",\n    \"impact\": \"light\",\n    \"data\": {\n        \"title\": \"University of Ibadan Post UTME Form Now Available!\",\n        \"content\": \"The University of Ibadan has officially announced that the Post UTME form is now available. This is a great opportunity for students who have been searching for a chance to secure their spot in the university.\\n\\nTo register for the Post UTME form, please visit our admissions page on the HQ site. Our admissions team will guide you through the registration process and ensure that you have a smooth experience.\\n\\n**Important Details:**\\n* The Post UTME form is now available.\\n* Interested candidates can register on our admissions page.\\n* Our admissions team will be available to assist with any questions or concerns.\\n\\nRegister now for the Post UTME form on our admissions page and take the first step towards achieving your academic goals!\",\n        \"tags\": \"University of Ibadan, Post UTME, Admission, Academic Success, Opportunity\"\n    },\n    \"reason\": \"Drafting a new post as requested.\"\n}', 'Page: https://admin.highqsolidacademy.com/ai_assistant', 'rejected', NULL, 1, '2026-07-14 18:55:14', NULL, '259cad30109555987b39ebea30ae4b25339148d1b47be88384333a0a630fc24e', NULL, NULL, '2026-07-14 18:53:43', '2026-07-14 18:55:14'),
(2, 1, 'insert', '{\n    \"action\": \"propose_action\",\n    \"action_type\": \"insert\",\n    \"target_table\": \"posts\",\n    \"impact\": \"light\",\n    \"data\": {\n        \"title\": \"University of Ibadan Post UTME Form Now Available!\",\n        \"content\": \"The University of Ibadan has officially announced that the Post UTME form is now available. This is a great opportunity for students who have been searching for a chance to secure their spot in the university.\\n\\nTo register for the Post UTME form, please visit our admissions page on the HQ site. Our admissions team will guide you through the registration process and ensure that you have a smooth experience.\\n\\n**Important Details:**\\n* The Post UTME form is now available.\\n* Interested candidates can register on our admissions page.\\n* Our admissions team will be available to assist with any questions or concerns.\\n\\nRegister now for the Post UTME form on our admissions page and take the first step towards achieving your academic goals!\",\n        \"tags\": \"University of Ibadan, Post UTME, Admission, Academic Success, Opportunity\",\n        \"featured_image\": \"https:\\/\\/highqsolidacademy.com\\/uploads\\/posts\\/ai_1784048072_df7012d3f6633c54.png\"\n    },\n    \"reason\": \"Drafting a new post as requested.\"\n}', 'Page: https://admin.highqsolidacademy.com/ai_assistant', 'executed', NULL, 1, '2026-07-14 18:55:05', NULL, '4fdb53a458a70709dafa4d5b703cf9eda07d17af7f26fe4e20ae5205c3377f8c', 1, '2026-07-14 18:55:10', '2026-07-14 18:54:51', '2026-07-14 18:55:10'),
