INSERT INTO `exam_questions` (`id`, `subject_id`, `question_text`, `explanation`, `difficulty`, `source_label`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
(1428, 10, 'Which option correctly matches the term \'Christian love\' with its meaning?', 'The correct match is Christian love: self-giving concern for God and other people expressed in conduct.', 'mixed', 'HQ-JAMB-CHRISTIAN-RELIGIOUS-KNOWLEDGE-CB5CC1E3FA', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1429, 10, 'Which option correctly matches the term \'stewardship\' with its meaning?', 'The correct match is stewardship: responsible management of abilities, resources and opportunities entrusted by God.', 'mixed', 'HQ-JAMB-CHRISTIAN-RELIGIOUS-KNOWLEDGE-6C99451698', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1430, 10, 'Which option correctly matches the term \'prayer\' with its meaning?', 'The correct match is prayer: communication with God through praise, confession, thanksgiving and requests.', 'mixed', 'HQ-JAMB-CHRISTIAN-RELIGIOUS-KNOWLEDGE-4B1CB51A0D', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1431, 11, 'Which option correctly matches the term \'asset\' with its meaning?', 'The correct match is asset: a resource controlled by a business from which future economic benefits are expected.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-0ADC4955D9', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1432, 11, 'Which option correctly matches the term \'liability\' with its meaning?', 'The correct match is liability: a present obligation of a business that is expected to require an outflow of resources.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-3CB05840D5', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1433, 11, 'Which option correctly matches the term \'capital\' with its meaning?', 'The correct match is capital: the owner\'s financial interest in a business.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-9585D318F0', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1434, 11, 'Which option correctly matches the term \'drawings\' with its meaning?', 'The correct match is drawings: cash or goods withdrawn from a business by the owner for personal use.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-2E0F1C9E42', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1435, 11, 'Which option correctly matches the term \'revenue\' with its meaning?', 'The correct match is revenue: income earned from the ordinary activities of a business.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-CC309C29A0', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1436, 11, 'Which option correctly matches the term \'expense\' with its meaning?', 'The correct match is expense: a cost incurred in the process of earning revenue.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-95000C0252', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1437, 11, 'Which option correctly matches the term \'debit\' with its meaning?', 'The correct match is debit: an entry made on the left side of an account.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-A9EE335D03', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1438, 11, 'Which option correctly matches the term \'credit\' with its meaning?', 'The correct match is credit: an entry made on the right side of an account.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-55065E4ED5', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1439, 11, 'Which option correctly matches the term \'journal\' with its meaning?', 'The correct match is journal: a book of original entry in which transactions are first recorded chronologically.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-7F0F5B0646', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1440, 11, 'Which option correctly matches the term \'ledger\' with its meaning?', 'The correct match is ledger: the principal book containing the individual accounts of a business.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-A456B1ADBB', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1441, 11, 'Which option correctly matches the term \'trial balance\' with its meaning?', 'The correct match is trial balance: a list of ledger balances prepared to test the arithmetic equality of debits and credits.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-0250FD88C6', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1442, 11, 'Which option correctly matches the term \'cash book\' with its meaning?', 'The correct match is cash book: a book of original entry used to record cash and bank transactions.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-D174FA3997', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1443, 11, 'Which option correctly matches the term \'bank reconciliation statement\' with its meaning?', 'The correct match is bank reconciliation statement: a statement explaining differences between the bank statement balance and the cash book balance.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-212D3DC152', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1444, 11, 'Which option correctly matches the term \'depreciation\' with its meaning?', 'The correct match is depreciation: the systematic allocation of the depreciable amount of a non-current asset over its useful life.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-972CC22DEC', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1445, 11, 'Which option correctly matches the term \'bad debt\' with its meaning?', 'The correct match is bad debt: an amount owed by a customer that is considered irrecoverable.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-6095E7B22D', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1446, 11, 'Which option correctly matches the term \'allowance for doubtful debts\' with its meaning?', 'The correct match is allowance for doubtful debts: an estimate of receivables that may not be collected.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-9D9870C4D5', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1447, 11, 'Which option correctly matches the term \'accrual\' with its meaning?', 'The correct match is accrual: an expense incurred but not yet paid at the end of an accounting period.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-4B3D6DE0BD', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1448, 11, 'Which option correctly matches the term \'prepayment\' with its meaning?', 'The correct match is prepayment: an expense paid in advance for a future accounting period.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-92EF32B02D', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1449, 11, 'Which option correctly matches the term \'inventory\' with its meaning?', 'The correct match is inventory: goods held for resale or materials held for use in production.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-3387F7A90C', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1450, 11, 'Which option correctly matches the term \'cost of goods sold\' with its meaning?', 'The correct match is cost of goods sold: the cost attributable to the goods that were sold during an accounting period.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-626A89CC74', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1451, 11, 'Which option correctly matches the term \'gross profit\' with its meaning?', 'The correct match is gross profit: sales revenue minus cost of goods sold.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-560CAB9C10', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1452, 11, 'Which option correctly matches the term \'net profit\' with its meaning?', 'The correct match is net profit: gross profit plus other income minus operating expenses.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-16B96A875D', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1453, 11, 'Which option correctly matches the term \'statement of financial position\' with its meaning?', 'The correct match is statement of financial position: a statement showing the assets, liabilities and equity of a business at a particular date.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-002630E877', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
(1454, 11, 'Which option correctly matches the term \'double-entry principle\' with its meaning?', 'The correct match is double-entry principle: the rule that every transaction has equal debit and credit effects.', 'mixed', 'HQ-JAMB-PRINCIPLES-OF-ACCOUNTS-BC4E2C67A0', 1, NULL, '2026-06-23 18:12:43', '2026-06-23 18:21:33'),
