INSERT INTO `testimonials` (`id`, `name`, `role_institution`, `testimonial_text`, `image_path`, `outcome_badge`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'ADEDUNYE KINGSLEY OLUWAPELUMI', 'Ambrose Ali University', 'I choose HQ because of the passion and zeal toward the success of every student', NULL, 'JAMB: 242', 1, 1, '2026-01-23 00:53:29', '2026-01-23 00:53:29'),
(2, 'Ayodele Joseph Teminijesu', 'Lasutech', 'Top-notch lessons! HQ is very patient and knows how to simplify even the toughest topics. The environment is conducive to learning and the focus on JAMB past questions was incredibly helpful. 10/10 recommended!', NULL, 'JAMB Success', 2, 1, '2026-01-23 00:53:29', '2026-01-23 00:53:29'),
(3, 'Fadele Oluwanifemi Abigail', 'Ladoke Akintola University Of Technology', 'At first, it was the only tutorial I\'ve been hearing people talking about. It has been said that the academy is really a high quality.', NULL, 'JAMB: 235', 3, 1, '2026-01-23 00:53:29', '2026-01-23 00:53:29'),
(4, 'Robinson Delight', 'Current Student', 'HQ tutorial is the best and they teach well', NULL, 'JAMB: 167', 4, 1, '2026-01-23 00:53:29', '2026-01-23 00:53:29'),
(5, 'Adeyemi Wahab Ayoade', 'Adekunle Ajasin University Akungba', 'I chose this tutorial because it is well-structured, engaging, and provides clear explanations that improve my understanding of the subject.', NULL, 'JAMB Success', 5, 1, '2026-01-23 00:53:29', '2026-01-23 00:53:29'),
(6, 'Ogunsanya Zainab Olayinka', 'Olabisi Onabanjo University', 'It stands out from other tutorials.', NULL, 'JAMB: 218', 6, 1, '2026-01-23 00:53:29', '2026-01-23 00:53:29');
INSERT INTO `tutors` (`id`, `name`, `slug`, `type`, `photo`, `short_bio`, `long_bio`, `qualifications`, `subjects`, `experience`, `contact_email`, `phone`, `rating`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES
(6, 'Raheem Omotolani', '-aheem-motolani', 'tutor', 'uploads/tutors/1758822852_c59684e11458.jpeg', '6 years of Experience', 'Solid academic credentials, a passion for teaching science and technology, and a desire to motivate the next generation of students.', 'NCE ( Biology/Computer Science), AOCOED  B.Sc Ed ( Intergrated Science Education), UNILAG  TRCN Certification', '[\"Biology\",\"Computer Science\"]', 0, NULL, NULL, NULL, 1, 1, '2025-10-05 02:01:40', '2025-12-28 05:50:32'),
(7, 'Adewole Daniel', '-dewole-aniel', 'tutor', 'uploads/tutors/dan.jpg', NULL, 'Competent economist and finance specialist with strong credentials and a keen analytical spirit.', 'AAT, B.Sc,  ACA', '[\"Financial Accounting\",\"Economics\",\" Statistics\"]', 0, NULL, NULL, NULL, 1, 1, '2025-10-05 11:43:17', '2025-12-28 05:50:35'),
(8, 'Aina Oluwasegun', '-ina-luwasegun', 'tutor', NULL, '4 years of experince', 'ICAN-certified, a skilled accountant committed to providing top-notch financial education.', 'ICAN (ACA)', '[\"Accounting\"]', 0, NULL, NULL, NULL, 1, 1, '2025-10-05 18:01:07', '2025-12-28 05:50:37'),
(9, 'Mide Oshifisan', '-ide-shifisan', 'tutor', 'uploads/tutors/mide.jpg', '4 years of experince', 'UI/UX educator and creative design specialist with a love for building distinctive brands and inspiring upcoming designers.', 'B.Sc', '[\"Pro Brand Designer \\/ Design Tutor\",\"UI\\/UX Tutor\"]', 0, NULL, NULL, NULL, 1, 1, '2025-10-05 18:02:43', '2025-12-28 05:50:39'),
(10, 'Akintunde Oreoluwa', '-kintunde-reoluwa', 'tutor', 'uploads/tutors/ore.jpg', '3 years of experience', 'Committed economics teacher with a solid academic background who is passionate about developing critical thinkers.', 'B.Sc(Ed) Economics', '[\"Economics\"]', 0, NULL, NULL, NULL, 1, 1, '2025-10-05 18:04:41', '2025-12-28 05:50:41'),
(11, 'Atobatele Temiloluwa', '-tobatele-emiloluwa', 'tutor', 'uploads/tutors/temi.jpg', '3 years of experience', 'Dedicated to developing sharp business brains, this versatile educator has experience in accounting, commerce, and economics.', 'Bsc.Ed', '[\"Economics\",\"Commerce\",\" Accounting.\"]', 0, NULL, NULL, NULL, 1, 1, '2025-10-05 18:12:35', '2025-12-28 05:50:45'),
(12, 'Osuntogun Opeyemi', 'osuntogun-opeyemi', 'tutor', 'uploads/tutors/ope.jpg', '3 years of experience', 'Competent maths teacher with a solid foundation in electrical and electronic engineering.', '', '[\"Mathematics\"]', 0, '', '', NULL, 1, 1, '2025-10-05 23:41:19', '2025-12-28 05:50:48'),
(14, 'Sanyaolu Samuel Obanijesu', 'sanyaolu-samuel-obanijesu', 'tutor', 'uploads/tutors/tutor_6950c275c0756_1766900341.jpg', 'Core Science Tutor', 'A versatile science specialist dedicated to mastering the core logic of Mathematics, Further Mathematics, and the laboratory sciences to ensure students remain \'Always Ahead of Others', '', '[\"Mathematics\",\"Physics\",\"Chemistry\",\"Biology\",\"Further Mathematics\"]', 0, '', '', NULL, 1, 1, '2025-12-28 05:35:41', '2026-07-07 19:39:38');
